    if(e.telegraph>0){ctx.strokeStyle='#ff555988';ctx.lineWidth=2;ctx.beginPath();ctx.arc(0,0,62*(1-e.telegraph/.72)+3,0,Math.PI*2);ctx.stroke();}ctx.restore();
    const bw=e.boss?50:20;if(e.boss||e.vida<e.maxVida){ctx.fillStyle='#251e20';ctx.fillRect(x-bw/2,y-(e.boss?23:15),bw,4);ctx.fillStyle=e.boss?'#ee5961':'#dd6d66';ctx.fillRect(x-bw/2+1,y-(e.boss?22:14),(bw-2)*e.vida/e.maxVida,2);}if(e.freeze>0){ctx.fillStyle='#a4ecf4';ctx.fillRect(x-4,y-13,8,2);}
